// Content with portions generated by generative AI platform
package org.eclipse.kura.internal.rest.auth.jwt;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.time.Duration;
import java.time.Instant;

import org.eclipse.kura.KuraAuthenticationFailedException;
import org.junit.Test;

public class RefreshTokenFamilySweepTest {

    private static final Instant PAST = Instant.now().minus(Duration.ofSeconds(1));
    private static final Instant FUTURE = Instant.now().plus(Duration.ofMinutes(1));

    private RefreshTokenFamilies families;
    private String activeFamilyId;
    private String expiredFamilyId;

    @Test
    public void startingAFamilySweepsExpiredFamilies() {
        givenFamiliesSweptEvery(Duration.ZERO);
        givenAnExpiredFamily();

        whenAFamilyStarts();

        thenTheExpiredFamilyIsNoLongerTracked();
    }

    @Test
    public void checkingAFamilySweepsExpiredFamilies() throws KuraAuthenticationFailedException {
        givenFamiliesSweptEvery(Duration.ZERO);
        givenAnActiveFamily();
        givenAnExpiredFamily();

        whenTheActiveFamilyIsChecked();

        thenTheExpiredFamilyIsNoLongerTracked();
    }

    @Test
    public void expiredFamiliesAreKeptUntilTheSweepIntervalElapses() {
        givenFamiliesSweptEvery(Duration.ofHours(1));
        givenAnExpiredFamily();

        whenAFamilyStarts();

        thenTheExpiredFamilyIsStillTracked();
    }

    private void givenFamiliesSweptEvery(final Duration sweepInterval) {
        this.families = new RefreshTokenFamilies(sweepInterval);
    }

    private void givenAnActiveFamily() {
        this.activeFamilyId = this.families.start(FUTURE);
    }

    private void givenAnExpiredFamily() {
        this.expiredFamilyId = this.families.start(PAST);
    }

    private void whenAFamilyStarts() {
        this.families.start(FUTURE);
    }

    private void whenTheActiveFamilyIsChecked() throws KuraAuthenticationFailedException {
        this.families.check(this.activeFamilyId, 0);
    }

    private void thenTheExpiredFamilyIsNoLongerTracked() {
        assertFalse(this.families.isTracked(this.expiredFamilyId));
    }

    private void thenTheExpiredFamilyIsStillTracked() {
        assertTrue(this.families.isTracked(this.expiredFamilyId));
    }
}
